// CORRECTED Code - Extracts correct "Last" price column
const htmlContent = $input.item.json.data || "";

if (!htmlContent || typeof htmlContent !== 'string') {
  return [{ json: { error: "No HTML content" } }];
}

const now = new Date();
const scrapeDate = now.toISOString().split('T')[0];
const scrapeTime = now.toTimeString().split(' ')[0];

const symbolsData = [
  { symbol: 'CBH26', month: 'Mar' },
  { symbol: 'CBJ26', month: 'Apr' },
  { symbol: 'CBK26', month: 'May' },
  { symbol: 'CBM26', month: 'Jun' },
  { symbol: 'CBN26', month: 'Jul' },
  { symbol: 'CBQ26', month: 'Aug' },
  { symbol: 'CBU26', month: 'Sep' },
  { symbol: 'CBV26', month: 'Oct' },
  { symbol: 'CBX26', month: 'Nov' },
  { symbol: 'CBZ26', month: 'Dec' }
];

const results = [];

for (const { symbol, month } of symbolsData) {
  const idx = htmlContent.indexOf(symbol);

  if (idx > -1) {
    // Get context AFTER the symbol (not before)
    // This ensures we get data from the same row
    const ctx = htmlContent.substring(idx, Math.min(htmlContent.length, idx + 800));

    // Look for the "Last" column value specifically
    // Pattern: symbol, then month/year, then the FIRST number is Last price
    const priceMatch = ctx.match(/CBH26[\s\S]{0,200}?<\/a>[\s\S]{0,200}?<div[^>]*>\s*([0-9]{2}\.[0-9]{2})\s*</);

    // Alternative: Use more specific pattern for "last" column
    const lastPriceMatch = ctx.match(/<div[^>]*class="[^"]*last[^"]*"[^>]*>\s*([0-9]{2}\.[0-9]{2})/i);

    // Try another pattern - look for first price after contract name
    const firstPriceMatch = ctx.match(/2026[^0-9]*([0-9]{2}\.[0-9]{2})/);

    const price = lastPriceMatch ? lastPriceMatch[1] : 
                  (priceMatch ? priceMatch[1] : 
                  (firstPriceMatch ? firstPriceMatch[1] : null));

    if (price) {
      // Find change value
      const changeMatch = ctx.match(/([+\-][0-9]\.[0-9]{2})/);

      // Find time
      const timeMatch = ctx.match(/([0-9]{2}:[0-9]{2})/);

      results.push({
        json: {
          symbol: symbol,
          month: month,
          year: "2026",
          contract: `${month} 2026`,
          price_usd: parseFloat(price),
          change: changeMatch ? parseFloat(changeMatch[1]) : null,
          website_update_time: timeMatch ? timeMatch[1] : "",
          scrape_date: scrapeDate,
          scrape_time: scrapeTime,
          source: "https://oilprice.com/futures/brent/",
          commodity: "Brent Crude Oil Futures"
        }
      });
    }
  }
}

if (results.length === 0) {
  return [{
    json: {
      error: "No contracts extracted",
      scrape_date: scrapeDate
    }
  }];
}

return results;

